75	class CocoaPods {
76	  CocoaPods({
77	    @required FileSystem fileSystem,
78	    @required ProcessManager processManager,
79	    @required XcodeProjectInterpreter xcodeProjectInterpreter,
80	    @required Logger logger,
81	    @required Platform platform,
82	  }) : _fileSystem = fileSystem,
83	      _processManager = processManager,
84	      _xcodeProjectInterpreter = xcodeProjectInterpreter,
85	      _logger = logger,
