12	/// For a given build, determines whether dependencies have changed since the
13	/// last call to processPods, then calls processPods with that information.
14	Future<void> processPodsIfNeeded(
15	  XcodeBasedProject xcodeProject,
16	  String buildDirectory,
17	  BuildMode buildMode,
18	) async {
19	  final FlutterProject project = xcodeProject.parent;
20	  // Ensure that the plugin list is up to date, since hasPlugins relies on it.
21	  await refreshPluginsList(project, macOSPlatform: project.macos.existsSync());
22	  if (!(hasPlugins(project) || (project.isModule && xcodeProject.podfile.existsSync()))) {
23	    return;
24	  }
25	  // If the Xcode project, Podfile, or generated xcconfig have changed since
26	  // last run, pods should be updated.
27	  final Fingerprinter fingerprinter = Fingerprinter(
28	    fingerprintPath: globals.fs.path.join(buildDirectory, 'pod_inputs.fingerprint'),
29	    paths: <String>[
30	      xcodeProject.xcodeProjectInfoFile.path,
31	      xcodeProject.podfile.path,
32	      xcodeProject.generatedXcodePropertiesFile.path,
33	    ],
34	    fileSystem: globals.fs,
35	    logger: globals.logger,
36	  );
37	
38	  final bool didPodInstall = await globals.cocoaPods.processPods(
39	    xcodeProject: xcodeProject,
40	    engineDir: flutterFrameworkDir(buildMode),
41	    dependenciesChanged: !fingerprinter.doesFingerprintMatch(),
42	  );
43	  if (didPodInstall) {
44	    fingerprinter.writeFingerprint();
45	  }
46	}
